[{"order":1,"type":"heading","text":"React Native Animated API vs. Reanimated 3: A Technical Comparison"},{"order":2,"type":"paragraph","text":"Building fluid, high-performance animations is crucial for a native-like user experience in React Native. Historically, developers relied heavily on the built-in Animated API. However, the introduction of React Native Reanimated 3 has shifted the paradigm by executing animations entirely on the UI thread using Worklets and Shared Values. This tutorial explores the architectural differences and provides practical code implementations for both approaches."},{"order":3,"type":"heading","text":"Understanding the Architectural Differences"},{"order":4,"type":"bullet_point","text":"Animated API (Bridge-based): Communicates across the React Native bridge for every frame, serializing data between the JavaScript thread and the native UI thread, which can cause frame drops (jank) during heavy JavaScript thread execution."},{"order":5,"type":"bullet_point","text":"Reanimated 3 (Worklets & UI Thread): Executes animation logic synchronously on the UI thread using Worklets. Shared Values act as a reactive data layer that bridges the JS and UI threads without blocking either."},{"order":6,"type":"heading","text":"Approach 1: The Built-in Animated API"},{"order":7,"type":"paragraph","text":"The standard Animated API uses Animated.Value and driver options to run animations. Below is an example of a simple fade and scale animation using the core library."},{"order":8,"type":"code","text":"import React, { useRef } from 'react';
import { Animated, Button, StyleSheet, View } from 'react-native';

export default function StandardAnimatedSample() {
  const scaleValue = useRef(new Animated.Value(1)).current;

  const handlePress = () => {
    Animated.timing(scaleValue, {
      toValue: 1.5,
      duration: 300,
      useNativeDriver: true,
    }).start(() => {
      Animated.timing(scaleValue, {
        toValue: 1,
        duration: 300,
        useNativeDriver: true,
      }).start();
    });
  };

  return (
    <View style={styles.container}>
      <Animated.View style={[styles.box, { transform: [{ scale: scaleValue }] }]} />
      <Button title="Animate Box" onPress={handlePress} />
    </View>
  );
}

const styles = StyleSheet.create({
  container: { flex: 1, justifyContent: 'center', alignItems: 'center' },
  box: { width: 100, height: 100, backgroundColor: '#3498db', marginBottom: 20 },
});"},{"order":9,"type":"heading","text":"Approach 2: Reanimated 3 with Shared Values and Worklets"},{"order":10,"type":"paragraph","text":"Reanimated 3 elevates animation logic by utilizing Shared Values to store mutable states that can be accessed synchronously on the UI thread. Worklets (functions marked with 'use worklet') run directly on the UI thread."},{"order":11,"type":"code","text":"import React from 'react';
import { Button, StyleSheet, View } from 'react-native';
import Animated, { useSharedValue, useAnimatedStyle, withSpring } from 'react-native-reanimated';

export default function ReanimatedSample() {
  const scale = useSharedValue(1);

  const animatedStyle = useAnimatedStyle(() => {
    return {
      transform: [{ scale: scale.value }],
    };
  });

  const handlePress = () => {
    scale.value = withSpring(scale.value === 1 ? 1.5 : 1);
  };

  return (
    <View style={styles.container}>
      <Animated.View style={[styles.box, animatedStyle]} />
      <Button title="Animate with Reanimated 3" onPress={handlePress} />
    </View>
  );
}

const styles = StyleSheet.create({
  container: { flex: 1, justifyContent: 'center', alignItems: 'center' },
  box: { width: 100, height: 100, backgroundColor: '#e74c3c', marginBottom: 20 },
});"},{"order":12,"type":"heading","text":"Performance and Use Case Summary"},{"order":13,"type":"bullet_point","text":"Choose Animated API for basic, isolated animations (fade-ins, simple translations) where adding an external dependency is unnecessary."},{"order":14,"type":"bullet_point","text":"Choose Reanimated 3 for gesture-driven interactions, complex chained animations, layout animations, and scenarios requiring unwavering 60/120 FPS performance regardless of JavaScript thread load."}]
